// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ModifierEntrancy, Bank} from "../src/ModifierEntrancy.sol";

contract InvMutTest is Test {
    ModifierEntrancy c;
    Caller a;
    Caller b;

    function setUp() public {
        c = new ModifierEntrancy();
        a = new Caller();
        b = new Caller();
    }

    function testFuzz_property(uint8 seed) public {
        Caller first = seed % 2 == 0 ? a : b;
        Caller second = seed % 2 == 0 ? b : a;

        // first eligible caller claims the airdrop
        first.go(address(c));
        assertTrue(first.ok(), "first airDrop should succeed");

        // second eligible caller (balance still zero) must also succeed:
        // the lock must have been released after the first call completed
        second.go(address(c));
        assertTrue(second.ok(), "lock must be released after airDrop");
    }
}

contract Caller is Bank {
    bool public ok;

    function go(address target) external {
        (bool success, ) = target.call(abi.encodeWithSignature("airDrop()"));
        ok = success;
    }
}
